'use strict';
document.title='OAU EEE — Department filing room';
const studyNotice=document.querySelector('.direction-bar > span');studyNotice.classList.add('study-meta');studyNotice.innerHTML='<span class="top-session">2026 / 2027 · Current session</span><span>INTERACTIVE PROTOTYPES · SYNTHETIC DATA</span>';
const css=document.createElement('link');css.rel='stylesheet';css.href='portal.css';document.head.append(css);
document.body.classList.add('files','portal');document.querySelector('[data-direction="files"]').classList.add('active');
const modelScript=document.createElement('script');modelScript.src='demo-model.js';modelScript.onload=start;modelScript.onerror=()=>{document.querySelector('#app').innerHTML='<p class="empty">Unable to load the demo. Refresh to retry.</p>'};document.head.append(modelScript);
function start(){
const M=window.DemoModel,key='eee-filing-room-v3';let state;try{state=JSON.parse(localStorage.getItem(key));if(!state||state.version!==3)state=M.seed();}catch{state=M.seed();}
let role='adviser',page='Overview',auth='workspace',selected=state.students[0].id,session=M.current,semester='Harmattan',course='EEE401',query='',level='',pagination=1,tab='Lecture',notice='',preview='Normal',storageError=false;const uploads=new Map();
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const labels={student:'Student',staff:'Lecturer / staff',adviser:'Part adviser',hod:'HOD'};
const menus={student:['Overview','My profile','Courses & registration','Results','Timetable','Learning resources','Requests & complaints','My adviser','Inbox','Notifications'],staff:['Overview','Staff profile','Course management','Results management','Student records','Requests & complaints','Timetable','Learning resources','Compose message','Inbox','Notifications'],adviser:['Overview','Staff profile','Student records','Academic file','Registration review','Requests & complaints','Advising records','Appointments','Timetable','Compose message','Inbox','Notifications'],hod:['Overview','Staff profile','Student records','Academic file','Assignments','Course oversight','Advising records','Approval queue','Requests & complaints','Timetable','Learning resources','Compose message','Inbox','Notifications','Reports','Decision history','Import & review']};
const self=()=>role==='student'?state.students[0].id:role;
const accessible=()=>state.students.filter(s=>M.studentIds(state,role).includes(s.id));
const courses=()=>state.courses.filter(c=>M.courseIds(state,role).includes(c.code));
const studentName=id=>state.students.find(s=>s.id===id)?.name||id;
const badge=s=>`<span class="status status-${esc(s.toLowerCase().split(' ')[0])}">${esc(s)}</span>`;
const btn=(action,text,extra='',primary=false)=>`<button type="button" class="pill ${primary?'orange':''}" data-action="${action}" ${extra}>${text}</button>`;
const go=(target,text=target)=>`<button class="text-button" data-page="${target}">${text} →</button>`;
const field=(name,label,type='text',value='',extra='')=>`<label class="field">${label}<input name="${name}" type="${type}" value="${esc(value)}" ${extra}></label>`;
const select=(name,label,options,value='')=>`<label class="field">${label}<select name="${name}">${options.map(o=>{const [v,t]=Array.isArray(o)?o:[o,o];return `<option value="${esc(v)}" ${String(v)===String(value)?'selected':''}>${esc(t)}</option>`}).join('')}</select></label>`;
const textarea=(name,label,value='',required=true)=>`<label class="field">${label}<textarea name="${name}" rows="4" ${required?'required':''}>${esc(value)}</textarea></label>`;
const form=(action,html,label='Save changes',extra='')=>`<form data-form="${action}" ${extra}>${html}<p class="form-error" role="alert"></p><button class="pill orange" type="submit">${label}</button></form>`;
const card=(title,body,eyebrow='')=>`<div class="paper-card">${eyebrow?`<span class="eyebrow">${eyebrow}</span>`:''}<h2>${title}</h2>${body}</div>`;
const stats=items=>`<div class="summary-grid">${items.map(([t,v,d])=>`<div class="summary-card">${t}<strong>${esc(v)}</strong><small>${esc(d)}</small></div>`).join('')}</div>`;
const empty=text=>`<div class="empty">${text}</div>`;
function table(head,rows){return `<div class="table-wrap" tabindex="0" role="region" aria-label="Scrollable data table"><table><thead><tr>${head.map(h=>`<th scope="col">${h}</th>`).join('')}</tr></thead><tbody>${rows.length?rows.map(r=>`<tr>${r.map(c=>`<td>${c}</td>`).join('')}</tr>`).join(''):`<tr><td colspan="${head.length}">${empty('No records match this selection.')}</td></tr>`}</tbody></table></div>`;}
function save(){try{localStorage.setItem(key,JSON.stringify(state));storageError=false;}catch{storageError=true;}}
function act(action,p){const next=structuredClone(state);M.apply(next,role,action,p);state=next;save();}
function modal(html){const d=document.querySelector('#record');document.querySelector('#record-content').innerHTML=html;if(!d.open)d.showModal();bind(document.querySelector('#record-content'));}
function close(){document.querySelector('#record').close();}
function feedback(text){notice=text;render();}
function prepareFile(filename,blob,previewText=''){const url=URL.createObjectURL(blob);modal(`<h2>Your file is ready.</h2><p>${esc(filename)}</p><a class="pill orange" href="${url}" download="${esc(filename)}">Save file</a>${previewText?`<details><summary>View file contents</summary><pre class="resource-preview">${esc(previewText)}</pre></details>`:''}<p class="form-help">If this browser does not support downloads, use the file contents above or open the prototype in a standard browser.</p>`);document.querySelector('#record').addEventListener('close',()=>URL.revokeObjectURL(url),{once:true});}
function download(filename,text,type='text/plain'){prepareFile(filename,new Blob([text],{type}),text);}
function csv(rows){return rows.map(row=>row.map(v=>{const s=String(v??'');return '"'+(/^[=+@-]/.test(s)?"'":'')+s.replace(/"/g,'""')+'"';}).join(',')).join('\r\n');}
function annotations(){const map={
'Overview':['Identity, assignments, announcements, deadlines and pending counts','Open a pending workflow','Continue the relevant submission or review',labels[role]+' scoped dashboard'],
'My profile':['Own contact and academic details','Edit contact information','Save confirmation; identifiers stay read-only','Student own profile'],
'Staff profile':['Designation, department and contact details','Edit contacts and office','Save confirmation','Current sample staff account'],
'Student records':['Scoped profile directory and identifiers','Search/filter/page, then open file','Open academic summary where permitted','Adviser current cohort or HOD; lecturers use course rosters'],
'Results':['Approved period grades, units and demo GPA/CGPA','Select period or prepare result download','Read or export approved rows','Own student record only'],
'Academic file':['Course selections, credit load and approved grades','Select student/period','Review academic progress and source limitations','Assigned adviser or HOD'],
'Course management':['Assigned courses and approved enrolled rosters','Open course, score editor or resources','Prepare results/resources for the course','Assigned lecturer'],
'Course oversight':['Department catalogue, units and lecturer coverage','Inspect a course and roster','Assign uncovered courses via Assignments','HOD'],
'Timetable':['Lectures/examinations, venues and changes','Switch schedule type; HOD edits time/venue','Students receive change notifications','Student/adviser level; lecturer course; HOD department'],
'Learning resources':['Course files and upload metadata','Preview/save; lecturers upload','Student receives new-material notification','Current accessible courses; assigned lecturer/HOD uploads'],
'My adviser':['Adviser contacts, shared guidance and appointment status','Contact adviser or request appointment','Assigned adviser confirms/declines','Own student cohort; private notes excluded'],
'Appointments':['Scoped appointment requests and reasons','Confirm or decline','Student receives appointment update','Assigned part adviser'],
'Compose message':['Audience, recipient, subject and body','Review then confirm demo send','Recipient inbox and notification update','Lecturer assigned course; adviser cohort; HOD department'],
'Inbox':['Received message body, sender and date','Open message','Mark local message as read','Messages addressed to the current demo role/student'],
'Notifications':['Decisions, materials, schedules and reminders','Mark one/all as read','Unread dashboard count updates','Current recipient only'],
'Decision history':['Submission, review, export and correction events','Inspect actor, time and comment','Trace decisions back to source records','HOD oversight'],
'Import & review':['Synthetic contact conflict and review state','Compare and accept sample correction','Profile and decision history update','HOD demo; actual staging integration pending'],
'Courses & registration':['Own course selections, units and status','Save draft or submit','Adviser reviews; student receives decision','Student; submitted/approved selections are locked'],
'Registration review':['Assigned cohort registrations and credit totals','Approve or return with comments','Student corrects returned selections','Current assigned part adviser'],
'Results management':['Assigned course roster and score draft','Enter/upload scores and submit','HOD approves; approved results become visible','Assigned lecturer; scores 0–100'],
'Approval queue':['Submitted results and escalated requests','Approve, return or respond','Notifications and decision history update','HOD only'],
'Assignments':['Lecturer-course and adviser-cohort assignments','Create or deactivate sample assignment','Demo scope updates immediately','HOD only; production administration uses Django admin'],
'Requests & complaints':['Scoped requests, attachments and responses','Submit, respond or escalate','Status and notifications update','Student own; lecturer course enquiries; adviser cohort; HOD all'],
'Advising records':['Guidance, follow-up dates and visibility','Save advising note','Shared notes appear in student adviser view','Assigned adviser; private notes visible to adviser/HOD'],
'Reports':['Approved result rows by period, level and course','Filter and export CSV','Download synthetic summary','HOD only']};const d=map[page]||['Synthetic '+page+' data','Use labelled page actions','Follow the related demo workflow',labels[role]+' workspace'];return `<details class="annotations"><summary>Wireframe notes for developers</summary><dl><dt>Data</dt><dd>${d[0]}</dd><dt>Main action</dt><dd>${d[1]}</dd><dt>Next step</dt><dd>${d[2]}</dd><dt>Permissions</dt><dd>${d[3]}</dd></dl><p>Demo permissions guide screen design. Production authentication, uploads, access checks and academic rules require backend implementation. The course catalogue and grading scale are illustrative.</p></details>`;}
function render(){if(auth!=='workspace'){authScreen();return;}const unread=state.notifications.filter(n=>n.recipient===self()&&!n.read).length;
document.querySelector('#app').innerHTML=`<div class="portal-layout"><aside class="sidebar"><a class="brand" href="?theme=files"><span class="brand-mark">↯</span><span>OAU / EEE<br><b>Department filing room</b></span></a>${select('role','Preview workspace',Object.entries(labels),role)}<nav aria-label="Workspace navigation">${menus[role].map((m,i)=>`<button data-page="${m}" ${page===m?'aria-current="page"':''}><span>${String(i+1).padStart(2,'0')}</span>${m}</button>`).join('')}</nav><div class="sidebar-bottom"><span class="eyebrow">Academic session</span><p>2026 / 2027</p><small>${role==='student'?'Your own student record':role==='hod'?'Department-wide oversight':role==='adviser'?'Current assigned cohorts':'Current lecturer assignments'}</small></div>${btn('logout','Log out')}</aside><div class="portal-main"><header class="workspace-bar"><span>Electrical & Electronic Engineering</span><div class="header-actions">${go('Notifications',`Notifications (${unread})`)}<span class="user-chip"><b>${role==='student'?esc(state.students[0].name):'Dr. O. Demo'}</b></span></div></header><div class="page-head"><div><span class="eyebrow">The filing room / ${labels[role]}</span><h1>${page==='Overview'?'Your department, within reach.':page}</h1><p>${role==='student'?`${esc(state.students[0].id)} · Part IV / 400 level`:role==='adviser'?'Support your assigned students and keep records in order.':role==='hod'?'Departmental files, decisions and people.':'Your assigned courses and teaching activities.'}</p></div></div><div class="prototype-note">Interactive demo · Synthetic data · Saved in this browser · ${btn('reset','Reset demo')}</div>${storageError?'<div class="note" role="alert">Browser storage is unavailable or full. Changes will last only until this page closes.</div>':''}${notice?`<div class="success-banner" role="status">${esc(notice)}</div>`:''}<div class="preview-controls">${select('preview','Preview screen state',['Normal','Loading','Empty','Error','Access denied','Session expired'],preview)}</div><section id="page-content">${preview==='Normal'?content():stateScreen()}</section>${annotations()}<footer class="portal-footer">OAU EEE / Student records & identification system<span>Filing room · Prototype 02</span></footer></div></div>`;bind(document.querySelector('#app'));}
function stateScreen(){if(preview==='Loading')return card('Loading records…','<div class="skeleton" aria-busy="true"></div><p role="status">Fetching workspace. Use the selector to return to normal.</p>');if(preview==='Empty')return card('Nothing here yet.',empty('New records and activities will appear here.')+btn('retry','Return to workspace'));if(preview==='Error')return card('We couldn’t load this page.','<p role="alert">Demo network error. Saved changes are safe.</p>'+btn('retry','Try again'));if(preview==='Access denied')return card('Access is restricted.','<p>The required assignment or permission is missing.</p>'+btn('retry','Back to workspace'));return card('Your session has expired.','<p>Sign in again to continue. Saved demo drafts remain available.</p>'+btn('signin','Sign in again'));}
function periods(withStudent=false){return `<form data-form="periods" class="periods">${withStudent?select('student','Student',accessible().map(s=>[s.id,s.name]),selected):''}${select('session','Session',[M.current,'2025/2026'],session)}${select('semester','Semester',['Harmattan','Rain'],semester)}<button class="pill">View period</button></form>`;}
function content(){const views={'Overview':overview,'My profile':profilePage,'Staff profile':profilePage,'Student records':directory,'Courses & registration':registrationPage,'Registration review':registrationReview,'Results':resultPage,'Academic file':resultPage,'Course management':coursePage,'Course oversight':coursePage,'Results management':resultManagement,'Timetable':timetablePage,'Learning resources':resourcePage,'Requests & complaints':requestsPage,'My adviser':adviserPage,'Appointments':appointmentsPage,'Advising records':notesPage,'Compose message':messagePage,'Inbox':inboxPage,'Notifications':notificationPage,'Assignments':assignmentPage,'Approval queue':approvalPage,'Reports':reportPage,'Decision history':historyPage,'Import & review':importPage};return views[page]?.()||empty('Choose a workspace page.');}
function overview(){const regs=state.registrations.filter(r=>M.studentIds(state,role).includes(r.student)&&r.status==='Submitted');const requests=visibleRequests().filter(r=>!['Resolved','Approved'].includes(r.status));const metrics=role==='student'?[['Current level',400,'Part IV'],['Registration',M.registration(state,state.students[0].id)?.status||'Not started','Harmattan · '+M.current],['Pending actions',requests.length+(M.registration(state,state.students[0].id)?.status==='Draft'?1:0),'Requests & registration']]:role==='hod'?[['Student files',state.students.length,'Five levels'],['Staff / course coverage',`1 / ${new Set(state.assignments.filter(a=>a.kind==='Lecturer'&&a.active).map(a=>a.target)).size}`,'Staff count / assigned courses'],['Pending approvals',state.results.filter(r=>r.status==='Submitted').length+state.requests.filter(r=>r.escalated&&!['Resolved','Approved'].includes(r.status)).length,'Results and escalated requests']]:role==='adviser'?[['Assigned students',accessible().length,'Current cohorts'],['Pending registrations',regs.length,'Awaiting review'],['Unresolved requests',requests.length,'Student support']]:[['Assigned courses',courses().length,'Current assignments'],['Result drafts',state.results.filter(r=>courses().some(c=>c.code===r.course)&&r.status==='Draft').length,'Continue score entry'],['Upcoming activities',state.timetable.filter(t=>courses().some(c=>c.code===t.course)).length,'Lectures & examinations']];const primary=role==='student'?'Courses & registration':role==='staff'?'Course management':role==='adviser'?'Registration review':'Approval queue';return `${stats(metrics)}<div class="overview-grid">${card('Your next step.',`<p>${role==='student'?'Registration deadline: 16 October 2026. Select courses and submit to your adviser.':role==='staff'?'Open assigned courses, share resources and prepare results for review.':role==='adviser'?'Review selections, respond to requests and record follow-up guidance.':'Review submissions, assign staff and publish decisions.'}</p>${go(primary,'Open '+primary.toLowerCase())}<div class="file-decoration" aria-hidden="true">EEE / STUDENT FILES</div>`,'Current session')}${card('Notes from the department.',state.messages.filter(m=>m.recipients.includes(self())).slice(0,2).map(m=>`<div class="message-preview"><small>${esc(m.sender)}</small><h3>${esc(m.subject)}</h3><p>${esc(m.body)}</p></div>`).join('')+go('Inbox'),'Correspondence')}</div><div class="section-head"><h2>Within reach.</h2></div><div class="quick-links">${menus[role].filter(m=>m!=='Overview').map(m=>`<button data-page="${m}">${m}<span>↗</span></button>`).join('')}</div>`;}
function profileDetails(s){return `<dl><dt>Matric number</dt><dd>${esc(s.id)}</dd><dt>Current level</dt><dd>${s.level}</dd><dt>Admission</dt><dd>${esc(s.admission)} · ${s.year}</dd><dt>Department</dt><dd>Electrical & Electronic Engineering</dd><dt>Email</dt><dd>${esc(s.email||'Not supplied')}</dd><dt>Phone</dt><dd>${esc(s.phone||'Not supplied')}</dd></dl>`;}
function profilePage(){const p=role==='student'?state.students[0]:state.staffProfile;return card(esc(p.name),role==='student'?profileDetails(p):`<dl><dt>Designation</dt><dd>${esc(p.designation)}</dd><dt>Department</dt><dd>Electrical & Electronic Engineering</dd></dl>`)+card('Contact information',form('profile',field('email','Email *','email',p.email,'required')+field('phone','Phone *','tel',p.phone,'required minlength="7"')+field(role==='student'?'address':'office',role==='student'?'Address':'Office','text',p.address||p.office),'Save contact details')+'<p class="form-help">Academic identifiers, level and designation remain read-only.</p>');}
function directory(){const filtered=accessible().filter(s=>(!level||String(s.level)===level)&&`${s.name} ${s.id}`.toLowerCase().includes(query.toLowerCase()));const count=Math.max(1,Math.ceil(filtered.length/3));pagination=Math.min(pagination,count);return card('Student index',`<form class="tools" data-form="search"><input class="search" name="query" type="search" aria-label="Search students" placeholder="Name or matric number" value="${esc(query)}">${select('level','Level',[['','All accessible levels'],...[...new Set(accessible().map(s=>s.level))]],level)}<button class="pill">Search</button></form>${role==='staff'?'<div class="note">Record access follows adviser assignments. View enrolled students through Course management.</div>':''}${table(['Student','Identifier','Level','File'],filtered.slice((pagination-1)*3,pagination*3).map(s=>[esc(s.name),s.id,s.level,btn('record','Open file',`data-id="${s.id}"`)]))}<div class="pagination">${btn('previous','Previous',pagination===1?'disabled':'')}<span>${filtered.length} files · Page ${pagination} of ${count}</span>${btn('next','Next',pagination===count?'disabled':'')}</div>`);}
function registrationPage(){const list=state.courses.filter(c=>c.level===state.students[0].level&&c.semester===semester);const r=M.registration(state,state.students[0].id,M.current,semester),locked=r&&!['Draft','Returned for correction'].includes(r.status);return card('Choose your courses.',`<form data-form="registration-period">${select('semester','Semester',['Harmattan','Rain'],semester)}<button class="pill">Change semester</button></form><div class="registration-status">${badge(r?.status||'Not started')}<span>${M.current} · ${semester}</span></div>${r?.comment?`<div class="note">Adviser: ${esc(r.comment)}</div>`:''}<form data-form="registration"><div class="course-selection">${list.map(c=>`<label><input type="checkbox" name="codes" value="${c.code}" ${r?.codes.includes(c.code)?'checked':''} ${locked?'disabled':''}><span><strong>${c.code} · ${esc(c.title)}</strong><small>${c.type} · ${c.units} units</small></span></label>`).join('')}</div><p id="credit-total" role="status">Credit load: ${(r?.codes||[]).reduce((n,code)=>n+state.courses.find(c=>c.code===code).units,0)} units</p><p class="form-error" role="alert"></p>${locked?'<p>Selections are locked while submitted or approved.</p>':'<button class="pill" name="intent" value="saveRegistration">Save draft</button> <button class="pill orange" name="intent" value="submitRegistration">Submit for adviser review</button>'}</form><p class="form-help">Course catalogue and credit requirements are illustrative.</p>`);}
function registrationReview(){const records=state.registrations.filter(r=>M.studentIds(state,role).includes(r.student)&&r.session===M.current);return card('Registration review',records.map(r=>`<article class="workflow-item"><div class="item-heading"><h3>${esc(studentName(r.student))}</h3>${badge(r.status)}</div><p>${r.semester} · ${r.codes.join(', ')} · ${r.codes.reduce((n,code)=>n+state.courses.find(c=>c.code===code).units,0)} units</p>${r.comment?`<p>${esc(r.comment)}</p>`:''}${r.status==='Submitted'?btn('review-registration','Review selection',`data-id="${r.id}"`):''}</article>`).join('')||empty('No registrations in assigned cohorts.'));}
function resultPage(){if(role!=='student'&&!accessible().length)return card('Academic file',empty('No files within your assignment.'));if(!accessible().some(s=>s.id===selected))selected=accessible()[0]?.id||state.students[0].id;const summary=M.summary(state,selected,session,semester),r=M.registration(state,selected,session,semester);return card('Academic summary',periods(role!=='student')+stats([['Period GPA',summary.gpa||'—','Approved synthetic results'],['CGPA',summary.cgpa||'—','Available demo history'],['Outstanding courses',summary.outstanding.length?summary.outstanding.join(', '):'Unknown','Incomplete academic history']])+table(['Course','Title','Units','Score','Grade'],summary.rows.map(r=>[r.code,esc(r.title),r.units,r.score,r.grade]))+btn('download-results','Download visible results',summary.rows.length?'':'disabled')+'<p class="form-help">Illustrative five-point scale. Missing results, exemptions and graduation eligibility cannot be inferred from incomplete history.</p>')+card('Course selections and progress',r?`${badge(r.status)}<p>${r.codes.join(', ')}<br>Credit load: ${r.codes.reduce((n,code)=>n+state.courses.find(c=>c.code===code).units,0)} units<br>Approved course results in this period: ${summary.rows.length}</p>${r.comment?`<div class="note">${esc(r.comment)}</div>`:''}`:empty('No registration recorded for this period.'));}
function coursePage(){return card(page==='Course oversight'?'Department course catalogue':'Your assigned courses',table(['Course','Title','Type / units','Lecturer','Action'],courses().map(c=>[c.code,esc(c.title),`${c.type} / ${c.units}`,esc(state.assignments.find(a=>a.active&&a.kind==='Lecturer'&&a.target===c.code)?.staff||'Unassigned'),btn('course-detail','Open course',`data-id="${c.code}"`)])))+card('Curriculum context','<p>Part IV sample catalogue · Harmattan and Rain semesters. Institutional curriculum and grading policy require verification.</p>');}
function resultManagement(){const list=courses();if(!list.length)return card('Results management',empty('No active course assignment.'));if(!list.some(c=>c.code===course))course=list[0].code;const period=state.courses.find(c=>c.code===course).semester,batch=state.results.find(r=>r.course===course&&r.session===M.current&&r.semester===period),roster=state.students.filter(s=>state.registrations.some(r=>r.status==='Approved'&&r.student===s.id&&r.codes.includes(course)&&r.session===M.current&&r.semester===period)),locked=batch&&!['Draft','Returned for correction'].includes(batch.status);return card('Prepare course results.',`<form data-form="result-course">${select('course','Course',list.map(c=>[c.code,c.code+' · '+c.title]),course)}<button class="pill">Open course</button></form><div class="registration-status">${badge(batch?.status||'Draft')}<span>${M.current} · ${period}</span></div>${batch?.comment?`<div class="note">HOD: ${esc(batch.comment)}</div>`:''}${locked?table(['Student','Identifier','Score'],roster.map(s=>[esc(s.name),s.id,batch.scores[s.id]??'—'])):`<label class="field">Upload CSV (student_id,score)<input type="file" id="score-upload" accept=".csv,text/csv"></label><p class="form-help">Use exact matric identifiers. Blank scores stay unknown in drafts.</p><form data-form="scores" data-semester="${period}">${table(['Student','Identifier','Score / 100'],roster.map(s=>[esc(s.name),s.id,`<input type="number" min="0" max="100" step="0.1" name="${s.id}" aria-label="Score for ${esc(s.name)}" value="${batch?.scores[s.id]??''}">`]))}<p class="form-error" role="alert"></p><button class="pill" name="intent" value="saveResult">Save draft</button> <button class="pill orange" name="intent" value="submitResult" ${roster.length?'':'disabled'}>Submit to HOD</button></form>`}`);}
function timetablePage(){return card('Your schedule',`<div class="tabs" role="group" aria-label="Schedule type">${['Lecture','Examination'].map(t=>btn('schedule-tab',t,`data-tab="${t}" aria-pressed="${tab===t}"`,tab===t)).join('')}</div>${table(['Course','Day / date','Time','Venue','Update'],state.timetable.filter(t=>courses().some(c=>c.code===t.course)&&t.kind===tab).map(t=>[t.course,esc(t.day),esc(t.time),esc(t.venue),esc(t.note||'No changes')+(role==='hod'?'<br>'+btn('edit-schedule','Edit',`data-id="${t.id}"`):'')]))}<p class="form-help">Synthetic schedule; staff examination rows illustrate examination duties.</p>`);}
function resourcePage(){return card('Course materials',table(['Course','Material','File','Actions'],state.resources.filter(r=>courses().some(c=>c.code===r.course)).map(r=>[r.course,esc(r.title),esc(r.filename),btn('preview-resource','Preview',`data-id="${r.id}"`)+' '+btn('download-resource','Download',`data-id="${r.id}"`)])))+(['staff','hod'].includes(role)?card('Share a course resource',form('resource',select('course','Course *',courses().map(c=>[c.code,c.code+' · '+c.title]))+field('title','Material title *','text','','required')+'<label class="field">File *<input name="file" type="file" required accept=".pdf,.txt,.png,.jpg,.jpeg"></label><p class="form-help">PDF, text or image, up to 5 MB. File contents last until reload; metadata is saved locally.</p>','Upload demo resource')):'');}
function visibleRequests(){return state.requests.filter(q=>role==='hod'||(role==='student'?q.student===state.students[0].id:role==='adviser'?M.studentIds(state,role).includes(q.student):q.category==='Course enquiry'&&M.courseIds(state,role).includes(q.course)));}
function requestsPage(){return (role==='student'?card('Send a request',form('request',select('category','Category',['Profile correction','Course enquiry','Academic concern','Complaint'])+select('course','Related course',courses().map(c=>c.code))+field('subject','Subject *','text','','required maxlength="160"')+textarea('body','Details *')+'<label class="field">Attachment (optional)<input name="attachment" type="file" accept=".pdf,.txt,.png,.jpg,.jpeg"></label><p class="form-help">Up to 5 MB. File contents remain available for this page session.</p>','Submit request')):'')+card(role==='student'?'Your request history':'Student requests',visibleRequests().map(q=>`<article class="workflow-item"><div class="item-heading"><h3>${esc(q.subject)}</h3>${badge(q.status)}</div><p>${esc(studentName(q.student))} · ${esc(q.category)}</p><p>${esc(q.body)}</p>${q.attachment?btn('request-attachment','View '+esc(q.attachment),`data-id="${q.id}"`):''}${q.responses.map(r=>`<div class="response"><strong>${esc(r.actor)}</strong><p>${esc(r.body)}</p><small>${new Date(r.date).toLocaleDateString('en-GB')}</small></div>`).join('')}${role!=='student'?btn('respond-request','Respond / update',`data-id="${q.id}"`):''}${role==='adviser'&&!q.escalated?' '+btn('escalate-request','Refer to HOD',`data-id="${q.id}"`):''}</article>`).join('')||empty('No requests in this workspace.'));}
function adviserPage(){const a=state.assignments.find(a=>a.kind==='Adviser'&&a.active&&Number(a.target)===state.students[0].level);return card('Your part adviser',a?`<h3>${esc(a.staff)}</h3><p>Part IV · ${M.current}<br>staff@example.test · Sample office E12</p>${go('Requests & complaints','Contact adviser')}${form('appointment',field('date','Preferred date *','date','','required min="2026-10-06"')+field('time','Preferred time *','time','','required')+textarea('reason','Reason *'),'Request appointment')}`:empty('No adviser currently assigned. Contact the departmental office.'))+card('Appointments',appointmentList(state.appointments.filter(a=>a.student===state.students[0].id)))+card('Shared advising notes',state.notes.filter(n=>n.student===state.students[0].id&&n.visibility==='Student and adviser').map(n=>`<div class="workflow-item"><p>${esc(n.body)}</p><small>Follow-up: ${esc(n.followup||'Not scheduled')}</small></div>`).join('')||empty('No shared guidance notes yet.'));}
function appointmentList(list){return list.map(a=>`<div class="workflow-item"><div class="item-heading"><h3>${esc(studentName(a.student))}</h3>${badge(a.status)}</div><p>${esc(a.date)} · ${esc(a.time)}<br>${esc(a.reason)}</p>${a.comment?`<p>${esc(a.comment)}</p>`:''}${role==='adviser'&&a.status==='Requested'?btn('appointment-review','Review appointment',`data-id="${a.id}"`):''}</div>`).join('')||empty('No appointment requests yet.');}
function appointmentsPage(){return card('Appointment requests',appointmentList(state.appointments.filter(a=>M.studentIds(state,role).includes(a.student))));}
function notesPage(){return (role==='adviser'?card('Guidance and follow-up',form('note',select('student','Student *',accessible().map(s=>[s.id,s.name]))+textarea('body','Guidance note *')+field('followup','Follow-up date','date')+select('visibility','Visibility',['Adviser and HOD only','Student and adviser']),'Save note')):'')+card('Advising records',state.notes.filter(n=>M.studentIds(state,role).includes(n.student)).map(n=>`<div class="workflow-item"><h3>${esc(studentName(n.student))}</h3><p>${esc(n.body)}</p><small>${esc(n.visibility)} · Follow-up: ${esc(n.followup||'Not set')}</small></div>`).join('')||empty('No notes yet.'));}
function messagePage(){const audiences=role==='staff'?[['course','Assigned course']]:role==='adviser'?[['individual','Individual student'],['level','Assigned cohort']]:[['individual','Individual student'],['level','Student level'],['course','Course cohort'],['adviser','Part adviser']];return card('A note with a clear destination.',form('message',select('audience','Audience',audiences)+select('target','Recipient',[])+field('subject','Subject *','text','','required maxlength="160"')+textarea('body','Message *'),'Review message'));}
function updateRecipients(){const f=document.querySelector('[data-form="message"]');if(!f)return;const a=f.elements.audience.value,options=a==='individual'?accessible().map(s=>[s.id,s.name]):a==='level'?[...new Set(accessible().map(s=>s.level))].map(l=>[l,l+' level']):a==='course'?courses().map(c=>[c.code,c.code+' · '+c.title]):[['adviser','Dr. O. Demo']];f.elements.target.innerHTML=options.map(([v,t])=>`<option value="${esc(v)}">${esc(t)}</option>`).join('');}
function inboxPage(){return card('Your inbox',state.messages.filter(m=>m.recipients.includes(self())).map(m=>`<button class="inbox-row" data-action="open-message" data-id="${m.id}"><span class="avatar">${m.read.includes(self())?'✓':'●'}</span><span><small>${esc(m.sender)} · ${new Date(m.date).toLocaleDateString('en-GB')}</small><strong>${esc(m.subject)}</strong><p>${esc(m.body.slice(0,100))}${m.body.length>100?'…':''}</p></span><span>↗</span></button>`).join('')||empty('No messages addressed to this workspace.'));}
function notificationPage(){const list=state.notifications.filter(n=>n.recipient===self());return card('Updates and reminders',btn('read-all','Mark all as read')+list.map(n=>`<div class="workflow-item"><div class="item-heading"><h3>${esc(n.title)}</h3>${badge(n.read?'Read':'Unread')}</div><p>${esc(n.body)}</p>${!n.read?btn('read-notification','Mark read',`data-id="${n.id}"`):''}</div>`).join('')+(list.length?'':empty('You’re all caught up.')));}
function assignmentPage(){return card('Current staff assignments',table(['Staff','Type','Course / level','Status','Action'],state.assignments.map(a=>[esc(a.staff),a.kind,esc(a.target),badge(a.active?'Active':'Inactive'),btn('assignment-toggle',a.active?'Deactivate':'Activate',`data-id="${a.id}"`)])))+card('Assign staff',form('assignment',select('kind','Assignment type',['Adviser','Lecturer'])+select('target','Level / course',[]),'Create demo assignment')+'<p class="form-help">Prototype assignment changes only. Production administration remains in Django admin.</p>');}
function updateAssignmentTargets(){const f=document.querySelector('[data-form="assignment"]');if(f)f.elements.target.innerHTML=(f.elements.kind.value==='Adviser'?[100,200,300,400,500]:state.courses.map(c=>c.code)).map(v=>`<option>${v}</option>`).join('');}
function approvalPage(){return card('Results awaiting approval',state.results.filter(r=>r.status==='Submitted').map(r=>`<div class="workflow-item"><div class="item-heading"><h3>${r.course}</h3>${badge(r.status)}</div><p>${r.session} · ${r.semester} · ${Object.keys(r.scores).length} scores</p>${btn('review-result','Review results',`data-id="${r.id}"`)}</div>`).join('')||empty('No results awaiting approval.'))+card('Escalated requests',state.requests.filter(q=>q.escalated&&!['Resolved','Approved'].includes(q.status)).map(q=>`<div class="workflow-item"><h3>${esc(q.subject)}</h3><p>${esc(studentName(q.student))}</p>${btn('respond-request','Review request',`data-id="${q.id}"`)}</div>`).join('')||empty('No escalated requests.'));}
function reportRows(){return state.students.filter(s=>!level||String(s.level)===level).flatMap(s=>M.summary(state,s.id,session,semester).rows.filter(r=>!course||r.code===course).map(r=>[s.name,s.id,s.level,session,semester,r.code,r.units,r.score,r.grade]));}
function reportPage(){return card('Academic summaries',`<form data-form="report-filters" class="report-filters">${select('session','Session',[M.current,'2025/2026'],session)}${select('semester','Semester',['Harmattan','Rain'],semester)}${select('level','Level',[['','All levels'],100,200,300,400,500],level)}${select('course','Course',[['','All courses'],...state.courses.map(c=>c.code)],course)}<button class="pill">Apply filters</button></form>${table(['Name','Identifier','Level','Session','Semester','Course','Units','Score','Grade'],reportRows().map(r=>r.map(esc)))}${btn('export-report','Export CSV',reportRows().length?'':'disabled')}<p class="form-help">Only approved synthetic result rows are included.</p>`);}
function historyPage(){return card('Decision history',table(['Date / time','Actor','Action','Record','Comment'],state.history.map(h=>[new Date(h.date).toLocaleString('en-GB'),esc(h.actor)+' / '+labels[h.role],esc(h.action),esc(h.subject),esc(h.comment)])));}
function importPage(){return card('Review before filing.',stats([['Incoming rows',1,'Sample conflict'],['Conflict',state.importReviewed?0:1,'Contact correction'],['Accepted',state.importReviewed?1:0,'Local preview']])+`<div class="workflow-item"><h3>EEE/2022/043 · Contact conflict</h3><p>Existing: ${esc(state.students[1].phone)}<br>Incoming: 0800 000 0043<br>Source: synthetic review batch</p>${state.importReviewed?badge('Accepted'):btn('review-import','Review correction')}</div><p class="form-help">Demonstrates review and provenance only. Real import staging is not connected.</p>`);}
function authScreen(){document.querySelector('#app').innerHTML=`<div class="auth-shell">${card(auth==='recovery'?'Reset your password.':auth==='expired'?'Your session has expired.':'Welcome to the filing room.',auth==='recovery'?form('recovery',field('email','Account email *','email','','required'),'Request demo reset')+btn('login-screen','Back to sign in'):`<p>${auth==='expired'?'Sign in again to resume saved demo work.':'Choose a workspace and use the sample credentials below.'}</p>${form('login',select('role','Demo workspace',Object.entries(labels),role)+field('username','Username *','text','demo','required')+field('password','Password *','password','','required'),'Sign in')}<p class="form-help">Demo credentials: <strong>demo / demo123</strong>. Do not enter real credentials.</p>${btn('recovery-screen','Forgot password?')}`)}<p class="prototype-note">Synthetic prototype · No production authentication or email delivery</p></div>`;bind(document.querySelector('#app'));}
function validateFile(file){if(!file||!file.size)throw new Error('Select a non-empty file.');if(file.size>5*1024*1024)throw new Error('Choose a file smaller than 5 MB.');if(!/\.(pdf|txt|png|jpe?g)$/i.test(file.name))throw new Error('Choose a PDF, text or image file.');}
function bind(root){
root.querySelectorAll('[data-page]').forEach(b=>b.onclick=()=>{if(!menus[role].includes(b.dataset.page))return;page=b.dataset.page;preview='Normal';notice='';pagination=1;query='';level='';render();document.querySelector('.page-head h1')?.scrollIntoView({block:'nearest'});});
const r=root.querySelector('[name="role"]');if(r&&auth==='workspace')r.onchange=e=>{role=e.target.value;page='Overview';selected=role==='student'?state.students[0].id:(accessible()[0]?.id||'');notice='';preview='Normal';render();};
const ps=root.querySelector('[name="preview"]');if(ps)ps.onchange=e=>{preview=e.target.value;render();};
root.querySelectorAll('[data-action]').forEach(b=>b.onclick=()=>{try{onAction(b.dataset.action,b.dataset);}catch(err){modal('<h2>Action unavailable</h2><p role="alert">'+esc(err.message)+'</p>');}});
root.querySelectorAll('form[data-form]').forEach(f=>f.onsubmit=async e=>{e.preventDefault();const err=f.querySelector('.form-error');if(err)err.textContent='';try{await onForm(f,new FormData(f),e.submitter);}catch(error){if(err)err.textContent=error.message;else modal('<h2>Please check this action.</h2><p role="alert">'+esc(error.message)+'</p>');}});
const mf=root.querySelector('[data-form="message"]');if(mf){updateRecipients();mf.elements.audience.onchange=updateRecipients;}const af=root.querySelector('[data-form="assignment"]');if(af){updateAssignmentTargets();af.elements.kind.onchange=updateAssignmentTargets;}
root.querySelectorAll('[name="codes"]').forEach(c=>c.onchange=()=>{const codes=[...root.querySelectorAll('[name="codes"]:checked')].map(c=>c.value);document.querySelector('#credit-total').textContent='Credit load: '+codes.reduce((n,code)=>n+state.courses.find(c=>c.code===code).units,0)+' units';});
const upload=root.querySelector('#score-upload');if(upload)upload.onchange=async()=>{try{const file=upload.files[0];if(!file)return;if(file.size>1024*1024)throw new Error('CSV must be smaller than 1 MB.');const lines=(await file.text()).trim().split(/\r?\n/);if(lines.shift().replace(/^\uFEFF/,'').trim()!=='student_id,score')throw new Error('CSV header must be student_id,score.');const f=document.querySelector('[data-form="scores"]'),updates=[],seen=new Set();for(const line of lines){const parts=line.split(',');if(parts.length!==2)throw new Error('Each row requires a student identifier and score.');const [sid,value]=parts.map(x=>x.trim());if(seen.has(sid))throw new Error('Duplicate row: '+sid);seen.add(sid);if(!f.elements.namedItem(sid))throw new Error('Student not enrolled: '+sid);if(value===''||!Number.isFinite(Number(value))||Number(value)<0||Number(value)>100)throw new Error('Scores must be 0–100.');updates.push([sid,value]);}if(!updates.length)throw new Error('No score rows.');updates.forEach(([sid,value])=>f.elements.namedItem(sid).value=value);f.querySelector('.form-error').textContent='CSV loaded. Save draft or submit.';}catch(err){modal('<h2>CSV could not be loaded</h2><p role="alert">'+esc(err.message)+'</p>');}};
}
async function onForm(f,data,submitter){const v=Object.fromEntries(data.entries()),action=f.dataset.form;
if(action==='login'){if(v.username!=='demo'||v.password!=='demo123')throw new Error('Use demo / demo123.');role=v.role;auth='workspace';page='Overview';preview='Normal';feedback('Signed in to the '+labels[role]+' demo.');return;}
if(action==='recovery'){modal('<h2>Demo recovery requested</h2><p>A production reset link would be sent if the account exists. No email was sent.</p><p>Use demo / demo123 to continue.</p>');return;}
if(action==='profile'){act('profile',v);feedback('Contact details saved.');return;}
if(action==='search'){query=v.query.trim();level=v.level;pagination=1;render();return;}
if(action==='registration-period'){semester=v.semester;render();return;}
if(action==='registration'){act(submitter?.value||'saveRegistration',{codes:data.getAll('codes'),semester});feedback(submitter?.value==='submitRegistration'?'Submitted. Switch to Part adviser → Registration review to continue.':'Registration draft saved.');return;}
if(action==='periods'){session=v.session;semester=v.semester;if(v.student)selected=v.student;render();return;}
if(action==='result-course'){course=v.course;render();return;}
if(action==='scores'){act(submitter?.value||'saveResult',{course,semester:f.dataset.semester,scores:v});feedback(submitter?.value==='submitResult'?'Submitted. Switch to HOD → Approval queue to continue.':'Result draft saved.');return;}
if(['registrationDecision','resultDecision','respondRequest','escalate','appointmentDecision'].includes(action)){act(action,{...v,id:f.dataset.id});close();feedback('Decision saved. Notifications and history updated.');return;}
if(action==='request'){const file=v.attachment;if(file.size)validateFile(file);act('request',{...v,attachment:file.size?file.name:''});const q=state.requests[0];q.course=v.category==='Course enquiry'?v.course:'';if(file.size)uploads.set(q.id,file);save();feedback('Request submitted. Your adviser can respond or refer it to HOD.');return;}
if(action==='appointment'){if(!state.assignments.some(a=>a.active&&a.kind==='Adviser'&&Number(a.target)===state.students[0].level))throw new Error('No adviser currently assigned.');act('appointment',v);feedback('Appointment requested. Check this page for the response.');return;}
if(action==='note'){act('note',v);feedback('Advising note saved with selected visibility.');return;}
if(action==='message'){if(!v.subject.trim()||!v.body.trim())throw new Error('Subject and message required.');modal(`<h2>Review your message.</h2><p>To: ${esc(f.elements.target.selectedOptions[0]?.textContent||'No recipient')}</p><h3>${esc(v.subject)}</h3><p class="message-body">${esc(v.body)}</p>${btn('confirm-message','Send demo message','',true)}`);document.querySelector('[data-action="confirm-message"]').onclick=()=>{try{act('message',v);close();page='Inbox';feedback('Message sent to selected demo recipients.');}catch(err){modal('<h2>Message not sent</h2><p role="alert">'+esc(err.message)+'</p>');}};return;}
if(action==='assignment'){act('assignment',v);feedback('Assignment created. Demo role scopes updated.');return;}
if(action==='resource'){const file=v.file;validateFile(file);act('resource',{course:v.course,title:v.title,filename:file.name,text:/\.txt$/i.test(file.name)?await file.text():''});uploads.set(state.resources[0].id,file);feedback('Resource added and enrolled students notified.');return;}
if(action==='timetable'){act('timetable',{...v,id:f.dataset.id});close();feedback('Schedule updated and students notified.');return;}
if(action==='report-filters'){session=v.session;semester=v.semester;course=v.course;level=v.level;render();return;}
}
function onAction(action,data){
if(action==='logout'){auth='login';notice='';authScreen();return;}if(action==='signin'){auth='expired';close();authScreen();return;}if(action==='login-screen'){auth='login';close();authScreen();return;}if(action==='recovery-screen'){auth='recovery';authScreen();return;}if(action==='retry'){preview='Normal';render();return;}
if(action==='reset'){modal('<h2>Reset the demo?</h2><p>This clears saved synthetic drafts, changes and decisions in this browser.</p>'+btn('confirm-reset','Reset sample data','',true));return;}
if(action==='confirm-reset'){state=M.seed();uploads.clear();save();close();selected=state.students[0].id;page='Overview';feedback('Sample data reset.');return;}
if(action==='previous'||action==='next'){pagination+=action==='next'?1:-1;render();return;}
if(action==='record'){const s=accessible().find(s=>s.id===data.id);if(!s)throw new Error('Student outside your scope.');modal(card(esc(s.name),profileDetails(s)+(['adviser','hod'].includes(role)?btn('open-academic','Open academic summary',`data-id="${s.id}"`):'')));return;}
if(action==='open-academic'){selected=data.id;page='Academic file';close();notice='';render();return;}
if(action==='review-registration'){const r=state.registrations.find(r=>r.id===data.id&&M.studentIds(state,role).includes(r.student));if(!r)throw new Error('Registration unavailable.');modal(`<h2>${esc(studentName(r.student))}</h2>${table(['Course','Units','Type'],r.codes.map(code=>{const c=state.courses.find(c=>c.code===code);return [code,c.units,c.type];}))}${form('registrationDecision',select('status','Decision',['Approved','Returned for correction'])+textarea('comment','Comment (required when returning)','',false),'Save decision',`data-id="${r.id}"`)}`);return;}
if(action==='course-detail'){const c=courses().find(c=>c.code===data.id);if(!c)throw new Error('Course outside your assignment.');const roster=state.students.filter(s=>state.registrations.some(r=>r.status==='Approved'&&r.student===s.id&&r.session===M.current&&r.codes.includes(c.code)));modal(`<h2>${c.code} · ${esc(c.title)}</h2><p>${c.type} · ${c.units} units · ${c.semester}</p>${table(['Enrolled student','Identifier','Level'],roster.map(s=>[esc(s.name),s.id,s.level]))}${role==='staff'?btn('open-score-editor','Manage results',`data-id="${c.code}"`):''}${role==='staff'||role==='hod'?btn('open-resources','Course resources'):''}`);return;}
if(action==='open-score-editor'){course=data.id;page='Results management';close();render();return;}if(action==='open-resources'){page='Learning resources';close();render();return;}
if(action==='download-results'){const s=M.summary(state,selected,session,semester);download('demo-results.csv',csv([['Synthetic export',selected,session,semester],['Course','Units','Score','Grade'],...s.rows.map(r=>[r.code,r.units,r.score,r.grade])]),'text/csv');return;}
if(action==='schedule-tab'){tab=data.tab;render();return;}
if(action==='edit-schedule'){const t=state.timetable.find(t=>t.id===data.id);modal(`<h2>Update ${t.course} schedule</h2>${form('timetable',field('time','Time *','text',t.time,'required')+field('venue','Venue *','text',t.venue,'required')+textarea('note','Change notice',t.note,false),'Publish change',`data-id="${t.id}"`)}`);return;}
if(action==='preview-resource'||action==='download-resource'){const r=state.resources.find(r=>r.id===data.id&&courses().some(c=>c.code===r.course));if(!r)throw new Error('Resource unavailable.');const file=uploads.get(r.id);if(action==='download-resource'){if(file){prepareFile(r.filename,file,r.text||'');}else if(r.text)download(r.filename,r.text);else throw new Error('File contents were not retained after reload. Re-upload the demo file.');return;}if(r.text){modal(`<h2>${esc(r.title)}</h2><pre class="resource-preview">${esc(r.text)}</pre>`);return;}if(!file)throw new Error('Demo file unavailable after reload. Re-upload to preview.');const url=URL.createObjectURL(file);modal(`<h2>${esc(r.title)}</h2>${file.type.startsWith('image/')?`<img class="resource-image" src="${url}" alt="Uploaded course material">`:`<iframe class="resource-frame" title="Course material preview" src="${url}"></iframe>`}`);document.querySelector('#record').addEventListener('close',()=>URL.revokeObjectURL(url),{once:true});return;}
if(action==='request-attachment'){const q=visibleRequests().find(q=>q.id===data.id);if(!q)throw new Error('Request outside your scope.');const file=uploads.get(q.id);if(!file)throw new Error('Attachments last only until this page reloads.');const url=URL.createObjectURL(file);modal(`<h2>${esc(q.attachment)}</h2><a class="pill" href="${url}" download="${esc(q.attachment)}">Download attachment</a>`);document.querySelector('#record').addEventListener('close',()=>URL.revokeObjectURL(url),{once:true});return;}
if(action==='respond-request'||action==='escalate-request'){const q=visibleRequests().find(q=>q.id===data.id);if(!q)throw new Error('Request outside your scope.');modal(`<h2>${esc(q.subject)}</h2><p>${esc(q.body)}</p>${form(action==='escalate-request'?'escalate':'respondRequest',(action==='respond-request'?select('status','Status',['In review','Resolved','Returned for correction',...(role==='hod'?['Approved']:[])]):'')+textarea('comment',action==='escalate-request'?'Referral reason *':'Response *'),'Save update',`data-id="${q.id}"`)}`);return;}
if(action==='appointment-review'){const a=state.appointments.find(a=>a.id===data.id);modal(`<h2>Appointment · ${esc(a.date)}</h2>${form('appointmentDecision',select('status','Decision',['Confirmed','Declined'])+textarea('comment','Response (optional)','',false),'Save decision',`data-id="${a.id}"`)}`);return;}
if(action==='open-message'){const m=state.messages.find(m=>m.id===data.id&&m.recipients.includes(self()));if(!m)throw new Error('Message unavailable.');if(!m.read.includes(self()))m.read.push(self());save();modal(`<span class="eyebrow">${esc(m.sender)}</span><h2>${esc(m.subject)}</h2><p class="message-body">${esc(m.body)}</p>`);return;}
if(action==='read-all'||action==='read-notification'){state.notifications.filter(n=>n.recipient===self()&&(action==='read-all'||n.id===data.id)).forEach(n=>n.read=true);save();render();return;}
if(action==='assignment-toggle'){act('toggleAssignment',{id:data.id});feedback('Assignment status updated. Demo scopes reflect the change.');return;}
if(action==='review-result'){const r=state.results.find(r=>r.id===data.id);modal(`<h2>Review ${r.course} results</h2>${table(['Student','Identifier','Score'],Object.entries(r.scores).map(([sid,score])=>[esc(studentName(sid)),sid,score]))}${form('resultDecision',select('status','Decision',['Approved','Returned for correction'])+textarea('comment','Comment (required for corrections)','',false),'Save decision',`data-id="${r.id}"`)}`);return;}
if(action==='export-report'){download('demo-academic-summary.csv',csv([['Name','Identifier','Level','Session','Semester','Course','Units','Score','Grade'],...reportRows()]),'text/csv');state.history.unshift({id:M.id(),actor:'HOD Demo',role:'hod',action:'Report exported',subject:session+' / '+semester,comment:'Synthetic approved rows',date:new Date().toISOString()});save();feedback('Report prepared and export recorded in history.');return;}
if(action==='review-import'){modal('<h2>Accept the contact correction?</h2><p>Fatima Ibrahim · EEE/2022/043<br>Source: synthetic review batch<br>Incoming phone: 0800 000 0043</p>'+btn('accept-import','Accept demo correction','',true));return;}
if(action==='accept-import'){if(role!=='hod')throw new Error('Only HOD can accept this correction.');state.students[1].phone='0800 000 0043';state.importReviewed=true;state.history.unshift({id:M.id(),actor:'HOD Demo',role,action:'Import correction accepted',subject:state.students[1].id,comment:'Synthetic phone correction',date:new Date().toISOString()});save();close();feedback('Sample correction accepted and recorded.');return;}
}
document.querySelector('#record').addEventListener('click',e=>{if(e.target===e.currentTarget){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)close();}});
render();
}
